old:
// Resortcompiled: WSR links an older RFL (Nov 2008) whose manager keeps the flag at +0x1B20
// (RFLiIsWorking @ 0x800FFB20: lwz r3,-0x3A78(r13); lwz r3,0x1B20(r3)); MKW's is at +0x1B34. Reading the
// MKW offset returned an unrelated non-zero field, so RFLWaitAsync spun forever on a task thread.
// The manager pointer lives at r13-0x3A78 = 0x806F6C60 in both games.
constexpr uint32_t kRflManagerPtrAddr = 0x806F6C60u;
constexpr uint32_t kWorkingFlagOffset = 0x1b20u;

new:
// The US program (SP2E01) links the newer RFL. RFLiIsWorking at 0x800FFB20 is
// lwz r3,-0x3A60(r13); lwz r3,0x1B34(r3). The manager pointer is at 0x806F6C60.
constexpr uint32_t kRflManagerPtrAddr = 0x806F6C60u;
constexpr uint32_t kWorkingFlagOffset = 0x1b34u;
